7	// The public /#/join waitlist. One page that becomes two: a wide viewport gets
8	// the "constellation" layout (copy settled in the lower third), a narrow one
9	// gets the "drift" layout (headline up top, capture at the bottom). Both ride
10	// the same drifting star field. The 620px breakpoint drives layout and copy
11	// together so they never disagree.
12	type Mode = "desktop" | "phone";
13	type Status = "idle" | "submitting" | "joined";
14	
15	const BREAKPOINT = 620;
16	
17	function initialMode(): Mode {
18	  return typeof window !== "undefined" && window.innerWidth >= BREAKPOINT
19	    ? "desktop"
20	    : "phone";
21	}
22	
23	// Copy shifts with the layout; each side keeps the wording it was designed with.
24	const COPY: Record<Mode, {
25	  headline: string;
26	  sub: string;
27	  cta: string;
28	  fine: string;
29	}> = {
30	  desktop: {
31	    headline: "Your people are a constellation.",
32	    sub: "Every person you meet becomes a point of light - and Euno keeps them from drifting away.",
33	    cta: "Join",
34	    fine: "Private beta",
35	  },
36	  phone: {
37	    headline: "The people you meet, never lost again.",
38	    sub: "A quiet memory layer over the people of your life. Get in early.",
39	    cta: "Request access",
40	    fine: "No spam. Invites go out in waves.",
41	  },
42	};
43	
44	function CheckIcon() {
45	  return (
46	    <svg viewBox="0 0 24 24" fill="none" stroke="#0a84ff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
47	      <path d="M20 6 9 17l-5-5" />
48	    </svg>
49	  );
50	}
51	
52	export function Waitlist() {
53	  const rootRef = useRef<HTMLDivElement | null>(null);
54	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
55	  const [mode, setMode] = useState<Mode>(initialMode);
56	  const [email, setEmail] = useState("");
57	  const [status, setStatus] = useState<Status>("idle");
58	  const [error, setError] = useState<string | null>(null);
59	  const join = useMutation(api.waitlist.joinWaitlist);
60	
61	  // Layout follows the page width, flipping at the same breakpoint the copy
62	  // uses so the two stay in step.
63	  useEffect(() => {
64	    const root = rootRef.current;
65	    if (root === null) return;
66	    const observer = new ResizeObserver(([entry]) => {
67	      setMode(entry.contentRect.width >= BREAKPOINT ? "desktop" : "phone");
68	    });
69	    observer.observe(root);
70	    return () => observer.disconnect();
71	  }, []);
72	
73	  // The drifting star field. Lives for the component's lifetime and tears
74	  // down its animation frame on unmount; a still frame under reduced motion.
75	  useEffect(() => {
76	    const canvas = canvasRef.current;
77	    if (canvas === null) return;
78	    return startDrift(canvas);
79	  }, []);
80	
81	  async function onSubmit(event: FormEvent) {
82	    event.preventDefault();
83	    setError(null);
84	    if (!isValidEmail(email)) {
85	      setError("Enter a valid email address.");
86	      return;
87	    }
88	    setStatus("submitting");
89	    try {
90	      await join({ email, source: mode });
91	      setStatus("joined");
92	    } catch (err) {
93	      setStatus("idle");
94	      // ConvexError carries our own server message; anything else is a network
95	      // or unexpected failure the person can just retry.
96	      setError(
97	        err instanceof ConvexError && typeof err.data === "string"
98	          ? err.data
99	          : "Something went wrong. Please try again.",
100	      );
101	    }
102	  }
103	
104	  const copy = COPY[mode];
105	
106	  return (
107	    <div ref={rootRef} className="waitlist" data-mode={mode}>
108	      <canvas ref={canvasRef} className="wl-sky" aria-hidden="true" />
109	      <div className="wl-content">
110	        {status === "joined" ? (
111	          <div className="wl-joined" role="status">
112	            <div className="wl-check" aria-hidden="true">
113	              <CheckIcon />
114	            </div>
115	            <p className="wl-checkline">You are on the list.</p>
116	            <p className="wl-sub wl-joined-sub">
117	              Thank you for joining us, to be in the true social that brings you to other people in your life
118	            </p>
119	          </div>
120	        ) : (
121	          <>
122	            <div className="wl-top">
123	              <span className="wl-eyebrow">Euno - private beta</span>
124	              <h1 className="wl-headline">{copy.headline}</h1>
125	            </div>
126	            <div className="wl-bottom">
127	              <p className="wl-sub">{copy.sub}</p>
128	              <form className="wl-form" onSubmit={onSubmit} noValidate>
129	                <input
130	                  className="wl-field"
131	                  type="email"
132	                  inputMode="email"
133	                  autoComplete="email"
134	                  placeholder="Your email"
135	                  aria-label="Email address"
136	                  value={email}
137	                  onChange={(event) => {
138	                    setEmail(event.target.value);
139	                    if (error !== null) setError(null);
140	                  }}
141	                />
142	                <button className="wl-go" type="submit" disabled={status === "submitting"}>
143	                  {status === "submitting" ? "Joining" : copy.cta}
144	                </button>
145	              </form>
146	              {error !== null ? (
147	                <p className="wl-error" role="alert">{error}</p>
148	              ) : (
149	                <p className="wl-fine">{copy.fine}</p>
150	              )}
151	            </div>
152	          </>
153	        )}
154	      </div>
155	    </div>
156	  );
157	}
158	
159	type Star = {
160	  x: number;
161	  y: number;
162	  size: number;
163	  base: number;
164	  sp: number;
165	  tw: number;
166	  hot: boolean;
167	};
168	
169	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
170	// stars move faster. Returns its own teardown. Ported from the approved
171	// prototype so the shipped page matches it exactly.
172	function startDrift(canvas: HTMLCanvasElement): () => void {
173	  const ctx = canvas.getContext("2d");
174	  if (ctx === null) return () => {};
175	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
176	  let w = 0;
177	  let h = 0;
178	  let raf = 0;
179	  let stars: Star[] = [];
180	
181	  function size() {
182	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
183	    w = canvas.clientWidth;
184	    h = canvas.clientHeight;
185	    canvas.width = w * dpr;
186	    canvas.height = h * dpr;
187	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
188	  }
189	
190	  function build() {
191	    size();
192	    const count = Math.min(300, Math.floor((w * h) / 3600));
193	    stars = [];
194	    for (let i = 0; i < count; i++) {
195	      const depth = Math.random();
196	      stars.push({
197	        x: Math.random() * w,
198	        y: Math.random() * h,
199	        size: 0.5 + depth * 1.6,
200	        base: 0.1 + depth * 0.45,
201	        sp: 0.05 + depth * 0.22,
202	        tw: Math.random() * 6.28,
203	        hot: Math.random() < 0.04,
204	      });
205	    }
206	  }
207	
208	  function frame(t: number) {
209	    const time = t / 1000;
210	    ctx!.clearRect(0, 0, w, h);
211	    for (const s of stars) {
212	      if (!reduce) {
213	        s.x += s.sp;
214	        if (s.x > w + 2) s.x = -2;
215	      }
216	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
217	      ctx!.beginPath();
218	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
219	      if (s.hot) {
220	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
221	        ctx!.shadowColor = "rgba(10,132,255,.8)";
222	        ctx!.shadowBlur = 6;
223	      } else {
224	        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
225	        ctx!.shadowBlur = 0;
226	      }
227	      ctx!.fill();
228	    }
229	    ctx!.shadowBlur = 0;
230	    if (!reduce) raf = requestAnimationFrame(frame);
231	  }
232	
233	  function onResize() {
234	    build();
235	    if (reduce) frame(0);
236	  }
237	
238	  build();
239	  if (reduce) frame(0);
240	  else raf = requestAnimationFrame(frame);
241	  window.addEventListener("resize", onResize);
242	
243	  return () => {
244	    cancelAnimationFrame(raf);
245	    window.removeEventListener("resize", onResize);
246	  };
247	}
248

