.wl-sub {
  margin: 0 0 22px;
  font-size: 18px;
  line-height: 1.55;
  color: #b8b8bd;
}

.wl-bottom {
  max-width: 460px;
}

.wl-form {
  display: flex;
  gap: 10px;
}

.wl-field {
  flex: 1;
  min-width: 0;
  height: 54px;
  padding: 0 18px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.06);
  font: inherit;
  font-size: 17px;
  color: #fff;
  -webkit-appearance: none;
  appearance: none;
  transition: border-color var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out),
    box-shadow var(--t-fast) var(--ease-out);
}

.wl-field::placeholder {
  color: #6e6e73;
}

.wl-field:hover {
  border-color: rgba(255, 255, 255, 0.24);
}

.wl-field:focus {
  outline: none;
  border-color: var(--accent);
  background: rgba(255, 255, 255, 0.09);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 14%, transparent);
}

.wl-go {
  height: 54px;
  padding: 0 20px;
  border: none;
  border-radius: var(--radius);
  background: var(--accent-fill);
  color: #fff;
  font: inherit;
  font-size: 17px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: transform var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out),
    box-shadow var(--t-fast) var(--ease-out);
}

.wl-go:hover {
  background: #178bff;
  box-shadow: 0 8px 24px rgba(0, 113, 227, 0.3);
}

.wl-go:active {
  transform: scale(0.97);
  box-shadow: 0 4px 12px rgba(0, 113, 227, 0.24);
}

.wl-go:disabled {
  opacity: 0.6;
  cursor: default;
}

.wl-fine {
  margin-top: 18px;
  font-size: 13px;
  color: #6e6e73;
}

.wl-error {
  margin-top: 18px;
  font-size: 13px;
  color: #ff6b60;
}

/* Success state */
.wl-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin-bottom: 20px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.18);
  animation: wl-rise-in 500ms var(--ease-out) both;
}

.wl-check svg {
  width: 28px;
  height: 28px;
}

.wl-checkline {
  margin: 0 0 12px;
  font-size: clamp(26px, 6vw, 36px);
  font-weight: 600;
  letter-spacing: -0.02em;
}

.wl-joined-sub {
  margin: 0;
}

/* ---- phone / drift: headline up top, capture at the bottom ---- */
.waitlist[data-mode="phone"] .wl-content {
  justify-content: space-between;
}

.waitlist[data-mode="phone"] .wl-headline {
  max-width: 12ch;
  font-size: clamp(38px, 11vw, 58px);
  font-weight: 700;
  letter-spacing: -0.045em;
  line-height: 0.94;
}

/* ---- desktop / constellation: copy centered in the viewport ---- */
.waitlist[data-mode="desktop"] .wl-content {
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 0 32px;
}

.waitlist[data-mode="desktop"] .wl-eyebrow {
  display: none;
}

.waitlist[data-mode="desktop"] .wl-top {
  margin-bottom: 18px;
}

.waitlist[data-mode="desktop"] .wl-headline {
  max-width: 16ch;
  font-size: clamp(34px, 5vw, 50px);
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.08;
}

/* Rhythm funnels toward the CTA: sub gets air above the form, caption hugs it. */
.waitlist[data-mode="desktop"] .wl-sub {
  margin: 0 auto 26px;
  max-width: 44ch;
}

.waitlist[data-mode="desktop"] .wl-bottom {
  max-width: 460px;
  margin: 22px auto 0;
}

.waitlist[data-mode="desktop"] .wl-form {
  max-width: 440px;
  margin: 0 auto;
}

.waitlist[data-mode="desktop"] .wl-fine,
.waitlist[data-mode="desktop"] .wl-error {
  margin-top: 13px;
  text-align: center;
}

/* On a real phone the inline field + button can get tight; stack under ~380px. */
@media (max-width: 380px) {
  .waitlist[data-mode="phone"] .wl-form {
    flex-direction: column;
  }
  .waitlist[data-mode="phone"] .wl-go {
    width: 100%;
  }
}

/* Entrances: the room settles in on load; the confirmation rises on submit. */
@keyframes wl-enter-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: none;

