+/// <reference types="vite/client" />
+import { afterEach, describe, expect, test, vi } from "vitest";
+import { renderConfirmation, sendWaitlistConfirmation } from "./emailClient";
+
+describe("renderConfirmation", () => {
+  test("greets the person by name in every part", () => {
+    const { subject, html, text } = renderConfirmation("Ada");
+    expect(subject).toBe("You're on the Euno waitlist");
+    expect(html).toContain("Hi Ada, you're on the list.");
+    expect(text).toContain("Hi Ada,");
+  });
+
+  test("escapes HTML in the name so a crafted name cannot inject markup", () => {
+    const { html } = renderConfirmation('<script>alert("x")</script>');
+    // The raw tag must never reach the HTML body...
+    expect(html).not.toContain("<script>");
+    // ...it lands as escaped entities instead.
+    expect(html).toContain("&lt;script&gt;");
+    expect(html).toContain("&quot;");
+  });
+
+  test("escapes an ampersand so the name renders as typed", () => {
+    const { html } = renderConfirmation("Tom & Jerry");
+    expect(html).toContain("Tom &amp; Jerry");
+    expect(html).not.toContain("Tom & Jerry");
+  });
+
+  test("leaves the plain-text part unescaped", () => {
+    // Text has no markup to break out of, so entities would be noise there.
+    const { text } = renderConfirmation("Tom & Jerry");
+    expect(text).toContain("Hi Tom & Jerry,");
+  });
+});
+
+describe("sendWaitlistConfirmation", () => {
+  const original = {
+    key: process.env.RESEND_API_KEY,
+    from: process.env.WAITLIST_FROM_EMAIL,
+  };
+
+  afterEach(() => {
+    vi.unstubAllGlobals();
+    if (original.key === undefined) delete process.env.RESEND_API_KEY;
+    else process.env.RESEND_API_KEY = original.key;
+    if (original.from === undefined) delete process.env.WAITLIST_FROM_EMAIL;
+    else process.env.WAITLIST_FROM_EMAIL = original.from;
+  });
+
+  test("skips (never sends, never throws) when credentials are unset", async () => {
+    delete process.env.RESEND_API_KEY;
+    delete process.env.WAITLIST_FROM_EMAIL;
+    const fetchSpy = vi.fn();
+    vi.stubGlobal("fetch", fetchSpy);
+
+    const result = await sendWaitlistConfirmation({
+      to: "a@b.com",
+      name: "Ada",
+    });
+
+    expect(result.status).toBe("skipped");
+    expect(fetchSpy).not.toHaveBeenCalled();
+  });
+
+  test("posts to Resend and reports sent once both credentials are set", async () => {
+    process.env.RESEND_API_KEY = "re_test_key";
+    process.env.WAITLIST_FROM_EMAIL = "Euno <hello@euno.app>";
+    const fetchSpy = vi.fn(async () => Response.json({ id: "email_123" }));
+    vi.stubGlobal("fetch", fetchSpy);
+
+    const result = await sendWaitlistConfirmation({
+      to: "a@b.com",
+      name: "Ada",
+    });
+
+    expect(result).toEqual({ status: "sent", id: "email_123" });
+    expect(fetchSpy).toHaveBeenCalledOnce();
+    const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
+    expect(url).toBe("https://api.resend.com/emails");
+    const body = JSON.parse(init.body as string);
+    expect(body.from).toBe("Euno <hello@euno.app>");
+    expect(body.to).toBe("a@b.com");
+    expect(body.subject).toBe("You're on the Euno waitlist");
+  });
+
+  test("reports failed (not thrown) when Resend rejects the request", async () => {
+    process.env.RESEND_API_KEY = "re_test_key";
+    process.env.WAITLIST_FROM_EMAIL = "hello@euno.app";
+    vi.stubGlobal(
+      "fetch",
+      async () => new Response("domain not verified", { status: 403 }),
+    );
+
+    const result = await sendWaitlistConfirmation({
+      to: "a@b.com",
+      name: "Ada",
+    });
+
+    expect(result.status).toBe("failed");
+  });
+});
diff --git a/convex/emailClient.ts b/convex/emailClient.ts
new file mode 100644
index 0000000..2db47b7
--- /dev/null
+++ b/convex/emailClient.ts
@@ -0,0 +1,116 @@
+// The waitlist confirmation email. Split in two on purpose: renderConfirmation
+// is a pure function (name in, {subject, html, text} out) so the templating and
+// HTML-escaping are unit-testable without any network, and sendWaitlistConfirmation
+// is the thin, env-gated transport. fetch is available in the default Convex
+// runtime, so this file needs no "use node".
+
+// The name is untrusted (anyone can submit any string) and lands inside HTML.
+// Escape the five characters that would otherwise break out of text content or
+// an attribute, so a crafted name can never inject markup into the message.
+function escapeHtml(value: string): string {
+  return value
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#39;");
+}
+
+export type Confirmation = {
+  subject: string;
+  html: string;
+  text: string;
+};
+
+// One template, two renderings that must say the same thing. The plain-text
+// part is what non-HTML clients (and spam filters) read, so it is not optional.
+export function renderConfirmation(name: string): Confirmation {
+  const safeName = escapeHtml(name);
+  const subject = "You're on the Euno waitlist";
+
+  const text = [
+    `Hi ${name},`,
+    "",
+    "You're on the Euno waitlist -- thank you for joining.",
+    "",
+    "Euno is a quiet memory layer over the people of your life, so the",
+    "people you meet never drift away. Invites go out in waves, and we'll",
+    "email you the moment yours is ready.",
+    "",
+    "-- The Euno team",
+  ].join("\n");
+
+  const html = `<!doctype html>
+<html lang="en">
+  <body style="margin:0;padding:0;background:#05070f;">
+    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#05070f;">
+      <tr>
+        <td align="center" style="padding:48px 24px;">
+          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:480px;">
+            <tr>
+              <td style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#f5f7fb;">
+                <p style="margin:0 0 24px;font-size:13px;letter-spacing:0.08em;text-transform:uppercase;color:#7c8496;">Euno &middot; private beta</p>
+                <h1 style="margin:0 0 16px;font-size:24px;line-height:1.3;font-weight:600;color:#ffffff;">Hi ${safeName}, you're on the list.</h1>
+                <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#c7cdda;">Thank you for joining the Euno waitlist.</p>
+                <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#c7cdda;">Euno is a quiet memory layer over the people of your life, so the people you meet never drift away. Invites go out in waves, and we'll email you the moment yours is ready.</p>
+                <p style="margin:32px 0 0;font-size:14px;color:#7c8496;">-- The Euno team</p>
+              </td>
+            </tr>
+          </table>
+        </td>
+      </tr>
+    </table>
+  </body>
+</html>`;
+
+  return { subject, html, text };
+}
+
+export type SendResult =
+  | { status: "sent"; id: string }
+  | { status: "skipped"; reason: string }
+  | { status: "failed"; error: string };
+
+// Provider-agnostic entry point. Today it posts to Resend; the whole HTTP shape
+// lives here so swapping providers touches this one function. Both credentials
+// are read from the Convex deployment env (like OPENAI_API_KEY): when either is
+// unset it returns "skipped" rather than throwing, which is the safe no-op that
+// lets the join flow ship before an email provider is wired up.
+export async function sendWaitlistConfirmation(args: {
+  to: string;
+  name: string;
+}): Promise<SendResult> {
+  const apiKey = process.env.RESEND_API_KEY;
+  const from = process.env.WAITLIST_FROM_EMAIL;
+  if (
+    apiKey === undefined ||
+    apiKey === "" ||
+    from === undefined ||
+    from === ""
+  ) {
+    return {
+      status: "skipped",
+      reason: "RESEND_API_KEY or WAITLIST_FROM_EMAIL is not set on the deployment",
+    };
+  }
+
+  const { subject, html, text } = renderConfirmation(args.name);
+  const response = await fetch("https://api.resend.com/emails", {
+    method: "POST",
+    headers: {
+      "Content-Type": "application/json",
+      Authorization: `Bearer ${apiKey}`,
+    },
+    body: JSON.stringify({ from, to: args.to, subject, html, text }),
+  });
+
+  if (!response.ok) {
+    return {
+      status: "failed",
+      error: `Resend responded ${response.status}: ${await response.text()}`,
+    };
+  }
+
+  const data = (await response.json()) as { id?: string };
+  return { status: "sent", id: data.id ?? "" };
+}
